execute_circuit_breaker_operation() {
    local timeout_seconds="${1:-30}"
    local failure_threshold="${2:-3}"
    log_info "Mock circuit breaker operation (timeout: ${timeout_seconds}s, threshold: ${failure_threshold})"
    
    # Simulate circuit breaker with 25% failure rate
    if [[ $((RANDOM % 4)) -eq 0 ]]; then
        log_warning "Mock circuit breaker: operation failed (simulated failure)"
        return 1
    else
        sleep 2
        log_success "Mock circuit breaker: operation succeeded"
        return 0
    fi
}

# Mock retry command execution
execute_retry_command() {
    local attempt_number="${1:-1}"
    local max_attempts="${2:-3}"
    log_info "Mock retry command execution (attempt $attempt_number/$max_attempts)"
    
    # Simulate work
    sleep 1
    
    # Simulate success after 2 attempts for realistic retry testing
    if [[ $attempt_number -ge 2 ]]; then
        log_success "Mock retry command: succeeded after $attempt_number attempts"
        return 0
    else
        log_warning "Mock retry command: failed on attempt $attempt_number"
        return 1
    fi
}

# Mock sequential iteration processing
execute_iteration_iterate_files_sequential() {
    local pattern="${1:-*}"
    log_info "Mock sequential iteration: processing files matching '$pattern'"
    
    # Simulate file processing
    sleep 0.5
    local files=("file1.txt" "file2.txt" "file3.txt")
    
    for file in "${files[@]}"; do
        log_info "Processing file: $file"
        sleep 0.5
    done
    
    log_success "Sequential iteration completed: processed ${#files[@]} files"
    return 0
}

# Mock fallback path execution for testing
execute_fallback_path() {
    local path_id="${1}"
    log_info "Mock fallback path execution: $path_id"
    
    # Simulate work
    sleep 1
    
    # Simulate success for primary_service_call, failure for others to test fallback behavior
    case "$path_id" in
        "primary_service_call")
            log_success "Primary service call succeeded"
            return 0
            ;;
        "secondary_service_call") 
            log_warning "Secondary service call failed"
            return 1
            ;;
        "cache_fallback_call")
            log_warning "Cache fallback failed"
            return 1
            ;;
        "default_response_call")
            log_success "Default response call succeeded"
            return 0
            ;;
        *)
            log_info "Unknown fallback path succeeded: $path_id"
            return 0
            ;;
    esac
}

# Workflow Execution

# Node: initialize_counter
set_var "CURRENT_VALUE" "0" "initialize_counter"

# Node: initialize_iteration_count
set_var "ITERATION_COUNT" "0" "initialize_iteration_count"

# Node: main_loop

# Node: main_loop (Main Processing Loop)
execute_loop_main_loop() {
    log_step "🔄 Starting Loop: Main Processing Loop"
    
    # Loop configuration
    local loop_counter=0
    local max_iterations=$(get_workflow_var "max_iterations" "100")
    local continue_loop=true
    local break_on="condition"
    
    # Loop execution with safety checks
    while [[ "$continue_loop" == "true" && $loop_counter -lt $max_iterations ]]; do
        log_debug "Loop iteration $loop_counter (max: $max_iterations)"
        
        # Set loop context variables for child nodes
        set_workflow_var "loop_index" "$loop_counter"
        set_workflow_var "loop_iteration" "$((loop_counter + 1))"
        
        # Evaluate loop condition
        local condition_result
                # Evaluate condition: CURRENT_VALUE < ${target_value}
        if (( $(get_workflow_var "CURRENT_VALUE" "0") < $(get_var "TARGET_VALUE" "main_loop") )); then
            condition_result="true"
        else
            condition_result="false"
        fi
        
        # Check if we should continue based on condition and break_on setting
        if [[ "$break_on" == "condition" ]]; then
            if [[ "$condition_result" != "true" ]]; then
                log_info "Loop exit condition met at iteration $loop_counter"
                break
            fi
        fi
        
        # Execute loop body (child nodes would be called here by the main executor)
        log_debug "Executing loop body for iteration $loop_counter"
        
        # This is where child nodes would be executed
        # The main executor will handle the edge routing to child nodes
        
        # Increment counter for next iteration
        ((loop_counter++))
        
        # Safety check for max iterations
        if [[ $loop_counter -ge $max_iterations ]]; then
            log_warning "Loop reached max iterations ($max_iterations), stopping"
            break
        fi
    done
    
    # Set final loop variables
    set_workflow_var "loop_final_count" "$loop_counter"
    set_workflow_var "loop_completed" "true"
    
    log_success "Loop completed after $loop_counter iterations"
}
execute_loop_main_loop

# Node: increment_counter
# Node: increment_counter
CURRENT_VALUE=$(echo $(($(get_workflow_var "CURRENT_VALUE" "0") + $(get_workflow_var "INCREMENT_STEP" "0"))))
set_var "CURRENT_VALUE" "$CURRENT_VALUE" "increment_counter"

# Node: increment_iteration
# Node: increment_iteration
ITERATION_COUNT=$(echo $(($(get_workflow_var "ITERATION_COUNT" "0") + 1)))
set_var "ITERATION_COUNT" "$ITERATION_COUNT" "increment_iteration"

# Node: log_progress
echo "Iteration $(get_var "ITERATION_COUNT" "log_progress"): current_value=$(get_var "CURRENT_VALUE" "log_progress"), target=$(get_var "TARGET_VALUE" "log_progress")"

# Node: check_early_termination
if true; then
  echo "Condition passed"
else
  echo "Condition failed"
fi

# Node: max_iterations_reached
echo "# ⚠️ Loop Terminated - Maximum Iterations Reached

The loop was stopped because it reached the maximum iteration limit.

**Final Results:**
- Current value: $(get_var "CURRENT_VALUE" "max_iterations_reached")
- Target value: $(get_var "TARGET_VALUE" "max_iterations_reached")
- Iterations completed: $(get_var "ITERATION_COUNT" "max_iterations_reached")
- Maximum allowed: $(get_var "MAX_ITERATIONS" "max_iterations_reached")
- Increment step: $(get_var "INCREMENT_STEP" "max_iterations_reached")

**Status**: Target not reached within iteration limit.

**Suggestions:**
- Increase maximum iterations
- Increase increment step
- Reduce target value
"

# Node: target_reached
echo "# 🎯 Loop Completed Successfully!

The target value was reached within the iteration limit.

**Final Results:**
- Final value: $(get_var "CURRENT_VALUE" "target_reached")
- Target value: $(get_var "TARGET_VALUE" "target_reached")
- Total iterations: $(get_var "ITERATION_COUNT" "target_reached")
- Maximum allowed: $(get_var "MAX_ITERATIONS" "target_reached")
- Increment step: $(get_var "INCREMENT_STEP" "target_reached")

**Performance:**
- Efficiency: $(get_var "ITERATION_COUNT" "target_reached")/$(get_var "MAX_ITERATIONS" "target_reached") iterations used
- Average increment: $(($(get_var "CURRENT_VALUE" "target_reached") / $(get_var "ITERATION_COUNT" "target_reached"))) per iteration

**Status**: ✅ Target reached successfully!
"

# Node: setup_second_loop
set_var "COUNTDOWN_VALUE" "" "setup_second_loop"

# Node: countdown_loop

# Node: countdown_loop (Countdown Loop)
execute_loop_countdown_loop() {
    log_step "🔄 Starting Loop: Countdown Loop"
    
    # Loop configuration
    local loop_counter=0
    local max_iterations=20
    local continue_loop=true
    local break_on="condition"
    
    # Loop execution with safety checks
    while [[ "$continue_loop" == "true" && $loop_counter -lt $max_iterations ]]; do
        log_debug "Loop iteration $loop_counter (max: $max_iterations)"
        
        # Set loop context variables for child nodes
        set_workflow_var "loop_index" "$loop_counter"
        set_workflow_var "loop_iteration" "$((loop_counter + 1))"
        
        # Evaluate loop condition
        local condition_result
                # Evaluate condition: COUNTDOWN_VALUE > 0
        if (( $(get_workflow_var "COUNTDOWN_VALUE" "0") > 0 )); then
            condition_result="true"
        else
            condition_result="false"
        fi
        
        # Check if we should continue based on condition and break_on setting
        if [[ "$break_on" == "condition" ]]; then
            if [[ "$condition_result" != "true" ]]; then
                log_info "Loop exit condition met at iteration $loop_counter"
                break
            fi
        fi
        
        # Execute loop body (child nodes would be called here by the main executor)
        log_debug "Executing loop body for iteration $loop_counter"
        
        # This is where child nodes would be executed
        # The main executor will handle the edge routing to child nodes
        
        # Increment counter for next iteration
        ((loop_counter++))
        
        # Safety check for max iterations
        if [[ $loop_counter -ge $max_iterations ]]; then
            log_warning "Loop reached max iterations ($max_iterations), stopping"
            break
        fi
    done
    
    # Set final loop variables
    set_workflow_var "loop_final_count" "$loop_counter"
    set_workflow_var "loop_completed" "true"
    
    log_success "Loop completed after $loop_counter iterations"
}
execute_loop_countdown_loop

# Node: decrement_countdown
# Node: decrement_countdown
COUNTDOWN_VALUE=$(echo $(($(get_workflow_var "COUNTDOWN_VALUE" "0") - $(get_workflow_var "INCREMENT_STEP" "0"))))
set_var "COUNTDOWN_VALUE" "$COUNTDOWN_VALUE" "decrement_countdown"

# Node: countdown_complete
echo "# 🔄 Both Loop Examples Completed!

## Loop Example Summary

### 1. Incrementing Loop (Count Up)
- **Objective**: Count from 0 to $(get_var "TARGET_VALUE" "countdown_complete")
- **Method**: Increment by $(get_var "INCREMENT_STEP" "countdown_complete") each iteration
- **Final value**: $(get_var "CURRENT_VALUE" "countdown_complete")
- **Iterations**: $(get_var "ITERATION_COUNT" "countdown_complete")

### 2. Decrementing Loop (Count Down)  
- **Objective**: Count from $(get_var "TARGET_VALUE" "countdown_complete") to 0
- **Method**: Decrement by $(get_var "INCREMENT_STEP" "countdown_complete") each iteration
- **Final value**: $(get_var "COUNTDOWN_VALUE" "countdown_complete")

## Loop Node Features Demonstrated

- **Condition-based termination**: Loop stops when condition becomes false
- **Maximum iteration safety**: Prevents infinite loops
- **Flexible break conditions**: Can break on condition or max iterations
- **Variable integration**: Loop conditions can use dynamic variables
- **Multiple loop patterns**: Both increment and decrement patterns
- **Progress tracking**: Monitor loop progress and performance

This example shows how loop nodes provide controlled, safe iteration with multiple termination mechanisms.
"

echo "Workflow completed successfully"
exit 0
